import icontract
from typing import List


@icontract.require(lambda a: all(a[i] <= a[i + 1] for i in range(len(a) - 1)))
@icontract.ensure(lambda a, result: 0 <= result <= len(a))
@icontract.ensure(lambda a, key, result: all(a[i] < key for i in range(result)))
@icontract.ensure(lambda a, key, result: all(a[i] >= key for i in range(result, len(a))))
def BinarySearch(a: List[int], key: int) -> int:
    lo, hi = 0, len(a)
    while lo < hi:
        mid = (lo + hi) // 2
        if a[mid] < key:
            lo = mid + 1
        else:
            hi = mid
    return lo
